// Package target: the output formats of compiled instances (Target), and
// what they share: where their files are (ProjectsDir, ProjectDir,
// InstanceDir, ProjectManifests), the mark of a generated file
// (Generated), the manifests of a project the deployer targets both write
// (Namespace, SecretStore), the checks of their options.
package target

import (
	"bytes"
	"errors"
	"fmt"
	"io/fs"
	"maps"
	"path"
	"slices"
	"strings"

	"go.yaml.in/yaml/v3"

	"github.com/okdp/okdp-compiler/internal/graph"
	"github.com/okdp/okdp-compiler/internal/okdp"
)

// Target: an output format: the files of compiled instances, path ->
// content, every path under ProjectsDir, all a deployer reads of the
// compiled tree. results are those of every instance of their namespaces,
// g their graph (graph.New).
type Target interface {
	Files(results []*okdp.Result, g *graph.Graph) (map[string][]byte, error)
}

// Keeper: a target that writes the platform's part of a project kept, one
// whose output is not written (output.Files: an instance of it refused):
// Kept gives, of p, the project as today's settings decide it
// (okdp.ProjectOf), the files the target writes of it that the platform
// decides, whatever its instances: its manifests (ProjectManifests), and
// in an instance's directory what gives the instance its identity, each
// marked generated; previous are the files the output written before
// holds of the project, by path, its instances' kept as they are but
// those Kept gives. The options are checked first.
type Keeper interface {
	Kept(p Project, previous map[string][]byte) (map[string][]byte, error)
}

// Generated: the first line of a file the compiler writes for a deployer,
// Go's mark of a generated file, which GitHub, linters and editors know.
const Generated = "# Code generated by okdp-compile. DO NOT EDIT.\n"

// ProjectsDir: the directory of every file of a target, projects/.
const ProjectsDir = "projects"

// ProjectDir: projects/<namespace>, the files of a namespace's instances.
func ProjectDir(namespace string) string { return path.Join(ProjectsDir, namespace) }

// InstanceDir: projects/<namespace>/instances/<release>, an instance's
// umbrella chart, in every target.
func InstanceDir(namespace, release string) string {
	return path.Join(ProjectDir(namespace), "instances", release)
}

// ProjectManifestsDir: project, the directory of a project's own manifests
// in its ProjectDir, which the deployer targets write for every project
// that has an instance: its Namespace (NamespaceFile), the platform's
// secret store in it (SecretStoreFile), the roles of its groups
// (AccessFile), the control plane's (ControlPlaneFile), and the identity
// of its releases; what the platform's entry point applies, before the
// instances.
const ProjectManifestsDir = "project"

// The files of ProjectManifestsDir the deployer targets share, the same
// whatever the target: one tree may hold the files of both.
const (
	// NamespaceFile: the project's Namespace (Namespace).
	NamespaceFile = "namespace.yaml"
	// SecretStoreFile: the platform's secret store in the project's
	// namespace, with its ServiceAccount (SecretStore); written when the
	// platform names a provider (Result.SecretStore).
	SecretStoreFile = "secret-store.yaml"
	// AccessFile: the RoleBindings of the project's groups in its
	// namespace (Access); written when a group has a role.
	AccessFile = "access.yaml"
	// ControlPlaneFile: the control plane's Role in the project's
	// namespace, and its RoleBinding (ControlPlane); written when the
	// platform names the control plane's identity.
	ControlPlaneFile = "control-plane.yaml"
	// NetworkPolicyFile: the NetworkPolicy of the project's namespace
	// (NetworkPolicy); written when the platform sets one, for a project
	// that is not one of the platform's own.
	NetworkPolicyFile = "network-policy.yaml"
)

// ProjectManifests: projects/<namespace>/project, a project's own
// manifests.
func ProjectManifests(namespace string) string {
	return path.Join(ProjectDir(namespace), ProjectManifestsDir)
}

// Project: a project, what its manifests are written from (okdp.Project):
// its namespace, whether it is one of the platform's own, the platform's
// secret store, the roles of its groups, the control plane's identity.
type Project = okdp.Project

// Projects: the projects of results, one per namespace that has a result,
// in namespace order: privileged when any of its results is
// (Result.Privileged), the first Result.SecretStore of the namespace that
// is set, and the first result's Access, ControlPlane and Network, which
// every result of a namespace has alike (its file's, the platform's), the
// network's claimers those of every result of the namespace (AddClaimers).
func Projects(results []*okdp.Result) []Project {
	byNamespace := map[string]*Project{}
	for _, res := range results {
		p, ok := byNamespace[res.Namespace]
		if !ok {
			p = &Project{Namespace: res.Namespace, Access: res.Access, ControlPlane: res.ControlPlane}
			if res.Network != nil {
				p.Network = &okdp.Network{Ingress: res.Network.Ingress}
			}
			byNamespace[res.Namespace] = p
		}
		p.Privileged = p.Privileged || res.Privileged
		if p.SecretStore == nil {
			p.SecretStore = res.SecretStore
		}
		if res.Network != nil {
			AddClaimers(p, res.Network.Claimers...)
		}
	}
	var out []Project
	for _, ns := range slices.Sorted(maps.Keys(byNamespace)) {
		out = append(out, *byNamespace[ns])
	}
	return out
}

// ProjectLabel: the label of every object a target writes for a project,
// okdp.io/project: <namespace>.
const ProjectLabel = "okdp.io/project"

// Namespace: the NamespaceFile of p, not marked, the same whatever the
// target: one tree may hold the files of both, which must agree. The
// Namespace, labelled ProjectLabel, with the Pod Security Admission labels
// of its project: baseline enforced, restricted audited and warned of;
// privileged enforced for one of the platform's own projects. And kept by
// both engines when its project is gone, its volumes with it, until an
// administrator deletes it: Flux's label kustomize.toolkit.fluxcd.io/prune:
// disabled, Argo CD's annotation argocd.argoproj.io/sync-options:
// Delete=false.
func Namespace(p Project) []byte {
	var l Lines
	l.Add("apiVersion: v1")
	l.Add("kind: Namespace")
	l.Add("metadata:")
	l.Add("  name: %q", p.Namespace)
	l.Add("  labels:")
	l.Add("    %s: %q", ProjectLabel, p.Namespace)
	l.Add("    kustomize.toolkit.fluxcd.io/prune: disabled")
	if p.Privileged {
		l.Add("    pod-security.kubernetes.io/enforce: privileged")
	} else {
		l.Add("    pod-security.kubernetes.io/enforce: baseline")
		l.Add("    pod-security.kubernetes.io/audit: restricted")
		l.Add("    pod-security.kubernetes.io/warn: restricted")
	}
	l.Add("  annotations:")
	l.Add("    argocd.argoproj.io/sync-options: Delete=false")
	return []byte(l.String())
}

// metadata: the metadata of an object SecretStore encodes.
type metadata struct {
	Name      string            `yaml:"name"`
	Namespace string            `yaml:"namespace"`
	Labels    map[string]string `yaml:"labels"`
}

// object: an object SecretStore encodes, its keys in this order.
type object struct {
	APIVersion string   `yaml:"apiVersion"`
	Kind       string   `yaml:"kind"`
	Metadata   metadata `yaml:"metadata"`
	Automount  *bool    `yaml:"automountServiceAccountToken,omitempty"`
	Spec       any      `yaml:"spec,omitempty"`
}

// SecretStore: the SecretStoreFile of p, not marked, nil when the platform
// names no provider (p.SecretStore nil): in the project's namespace, the
// ServiceAccount the store authenticates with (its token is not mounted:
// External Secrets requests one) and the SecretStore of the platform's
// name, its provider as the platform writes it, both labelled
// ProjectLabel. Encoded, not written line by line: the store's name and
// its provider are the platform's own text.
func SecretStore(p Project) ([]byte, error) {
	s := p.SecretStore
	if s == nil {
		return nil, nil
	}
	labels := map[string]string{ProjectLabel: p.Namespace}
	automount := false
	var buf bytes.Buffer
	enc := yaml.NewEncoder(&buf)
	enc.SetIndent(2)
	for _, o := range []object{
		{APIVersion: "v1", Kind: "ServiceAccount", Metadata: metadata{s.ServiceAccount, p.Namespace, labels}, Automount: &automount},
		{APIVersion: "external-secrets.io/v1", Kind: "SecretStore", Metadata: metadata{s.Name, p.Namespace, labels}, Spec: map[string]any{"provider": s.Provider}},
	} {
		if err := enc.Encode(o); err != nil {
			return nil, fmt.Errorf("%s: %s: %w", p.Namespace, SecretStoreFile, err)
		}
	}
	return buf.Bytes(), nil
}

// ClusterRole: the ClusterRole of Kubernetes a role of a project's group
// is bound to in its namespace: the built-in aggregated view, edit and
// admin.
func ClusterRole(r okdp.Role) string {
	switch r {
	case okdp.RoleViewer:
		return "view"
	case okdp.RoleEditor:
		return "edit"
	}
	return "admin"
}

// AccessName: okdp-access-<role>, the RoleBinding of the groups of a role
// in a project's namespace.
func AccessName(r okdp.Role) string { return "okdp-access-" + string(r) }

// Groups: the groups of p of the role r, in name order.
func Groups(p Project, r okdp.Role) []string {
	var out []string
	for _, g := range slices.Sorted(maps.Keys(p.Access.Groups)) {
		if p.Access.Groups[g] == r {
			out = append(out, g)
		}
	}
	return out
}

// Access: the AccessFile of p, not marked, the same whatever the target;
// nil when no group has a role: in the project's namespace, for each
// role that has groups, least first, the RoleBinding AccessName of its
// groups, each a subject of kind Group named the platform's prefix and
// the group's name (Access.GroupPrefix: as the API server names the
// groups of its OIDC users), to the ClusterRole of the role
// (ClusterRole), labelled ProjectLabel. Privileged or not: a project's
// people have the roles of its file in its namespace alone.
func Access(p Project) []byte {
	var l Lines
	for _, r := range okdp.Roles() {
		groups := Groups(p, r)
		if len(groups) == 0 {
			continue
		}
		if l.Len() > 0 {
			l.Add("---")
		}
		l.Add("apiVersion: rbac.authorization.k8s.io/v1")
		l.Add("kind: RoleBinding")
		l.Add("metadata:")
		l.Add("  name: %s", AccessName(r))
		l.Add("  namespace: %q", p.Namespace)
		l.Add("  labels:")
		l.Add("    %s: %q", ProjectLabel, p.Namespace)
		l.Add("roleRef:")
		l.Add("  apiGroup: rbac.authorization.k8s.io")
		l.Add("  kind: ClusterRole")
		l.Add("  name: %s", ClusterRole(r))
		l.Add("subjects:")
		for _, g := range groups {
			l.Add("  - apiGroup: rbac.authorization.k8s.io")
			l.Add("    kind: Group")
			l.Add("    name: %q", p.Access.GroupPrefix+g)
		}
	}
	if l.Len() == 0 {
		return nil
	}
	return []byte(l.String())
}

// ControlPlaneName: okdp-control-plane, the control plane's Role in a
// project's namespace, and its RoleBinding.
const ControlPlaneName = "okdp-control-plane"

// ControlPlaneRules: the rules of the control plane's Role in a project's
// namespace, what okdp-control-plane-server does there and nothing more:
// a Secret by name, never listed (the credentials of its connections, of
// its secret stores); its pods read, listed, deleted (a user's left by an
// instance deleted), their logs and metrics read; its events listed (why
// an instance is not ready); its volumes read, listed, deleted (a user's,
// with the pods); its SecretStores and ExternalSecrets, its
// SparkApplications, watched too, written. Each rule apiGroups,
// resources, verbs.
var ControlPlaneRules = [][3][]string{
	{{""}, {"secrets"}, {"get", "create", "update", "delete"}},
	{{""}, {"pods"}, {"get", "list", "delete"}},
	{{""}, {"pods/log"}, {"get"}},
	{{""}, {"events"}, {"list"}},
	{{""}, {"persistentvolumeclaims"}, {"get", "list", "delete"}},
	{{"metrics.k8s.io"}, {"pods"}, {"list"}},
	{{"external-secrets.io"}, {"secretstores", "externalsecrets"}, {"get", "list", "create", "update", "delete"}},
	{{"sparkoperator.k8s.io"}, {"sparkapplications"}, {"get", "list", "watch", "create", "update", "delete"}},
}

// ControlPlane: the ControlPlaneFile of p, not marked, the same whatever
// the target; nil when the platform has no control plane
// (Project.ControlPlane nil): in the project's namespace, privileged or
// not, the Role ControlPlaneName of ControlPlaneRules and the RoleBinding
// of the control plane's ServiceAccount to it, labelled ProjectLabel: the
// control plane holds no Secret of a namespace that is no project's.
func ControlPlane(p Project) []byte {
	sa := p.ControlPlane
	if sa == nil {
		return nil
	}
	list := func(xs []string) string {
		q := make([]string, len(xs))
		for i, x := range xs {
			q[i] = fmt.Sprintf("%q", x)
		}
		return "[" + strings.Join(q, ", ") + "]"
	}
	var l Lines
	l.Add("apiVersion: rbac.authorization.k8s.io/v1")
	l.Add("kind: Role")
	l.Add("metadata:")
	l.Add("  name: %s", ControlPlaneName)
	l.Add("  namespace: %q", p.Namespace)
	l.Add("  labels:")
	l.Add("    %s: %q", ProjectLabel, p.Namespace)
	l.Add("rules:")
	for _, r := range ControlPlaneRules {
		l.Add("  - apiGroups: %s", list(r[0]))
		l.Add("    resources: %s", list(r[1]))
		l.Add("    verbs: %s", list(r[2]))
	}
	l.Add("---")
	l.Add("apiVersion: rbac.authorization.k8s.io/v1")
	l.Add("kind: RoleBinding")
	l.Add("metadata:")
	l.Add("  name: %s", ControlPlaneName)
	l.Add("  namespace: %q", p.Namespace)
	l.Add("  labels:")
	l.Add("    %s: %q", ProjectLabel, p.Namespace)
	l.Add("roleRef:")
	l.Add("  apiGroup: rbac.authorization.k8s.io")
	l.Add("  kind: Role")
	l.Add("  name: %s", ControlPlaneName)
	l.Add("subjects:")
	l.Add("  - kind: ServiceAccount")
	l.Add("    name: %q", sa.Name)
	l.Add("    namespace: %q", sa.Namespace)
	return []byte(l.String())
}

// AddClaimers: namespaces added to the claimers of p's network policy,
// sorted, once each, p's own left out; none without a policy.
func AddClaimers(p *Project, namespaces ...string) {
	if p.Network == nil {
		return
	}
	n := *p.Network
	n.Claimers = slices.Clone(n.Claimers)
	for _, ns := range namespaces {
		if ns != p.Namespace && !slices.Contains(n.Claimers, ns) {
			n.Claimers = append(n.Claimers, ns)
		}
	}
	slices.Sort(n.Claimers)
	p.Network = &n
}

// NetworkPolicyName: okdp-project, the NetworkPolicy of a project's
// namespace.
const NetworkPolicyName = "okdp-project"

// NetworkPolicy: the NetworkPolicyFile of p, not marked, the same
// whatever the target; nil when the platform sets no policy
// (Project.Network nil) or p is one of the platform's own (an ingress
// controller, an operator's webhooks, reached from outside the cluster
// or from the API server, which no namespace names). In the project's
// namespace, labelled ProjectLabel, a NetworkPolicy of every pod that
// denies every ingress but from the pods of the namespace, from those of
// the platform's ingress namespaces (Network.Ingress) and from those of
// the namespaces whose claims the project provides (Network.Claimers),
// each namespace by its name (kubernetes.io/metadata.name, which the API
// server sets). Egress is not restricted: what a pod reaches is guarded
// by the policy of the namespace it reaches, and a project's services
// reach the API server, the identity provider, object stores and
// networks the compiler does not know.
func NetworkPolicy(p Project) []byte {
	n := p.Network
	if n == nil || p.Privileged {
		return nil
	}
	var l Lines
	l.Add("apiVersion: networking.k8s.io/v1")
	l.Add("kind: NetworkPolicy")
	l.Add("metadata:")
	l.Add("  name: %s", NetworkPolicyName)
	l.Add("  namespace: %q", p.Namespace)
	l.Add("  labels:")
	l.Add("    %s: %q", ProjectLabel, p.Namespace)
	l.Add("spec:")
	l.Add("  podSelector: {}")
	l.Add("  policyTypes: [Ingress]")
	l.Add("  ingress:")
	l.Add("    - from:")
	l.Add("        - podSelector: {}")
	if from := slices.Concat(n.Ingress, n.Claimers); len(from) > 0 {
		var q []string
		for _, ns := range from {
			if !slices.Contains(q, fmt.Sprintf("%q", ns)) {
				q = append(q, fmt.Sprintf("%q", ns))
			}
		}
		l.Add("    - from:")
		l.Add("        - namespaceSelector:")
		l.Add("            matchExpressions:")
		l.Add("              - key: kubernetes.io/metadata.name")
		l.Add("                operator: In")
		l.Add("                values: [%s]", strings.Join(q, ", "))
	}
	return []byte(l.String())
}

// CheckPrefix: nil when prefix, the path of the tree in the repository a
// deployer reads (a target's PathPrefix, of the field named field), is ""
// or a relative path without an empty, . or .. segment.
func CheckPrefix(field, prefix string) error {
	if prefix != "" && !fs.ValidPath(prefix) || prefix == "." {
		return fmt.Errorf("%s %q: the path of the tree in the repository, relative, without an empty, . or .. segment", field, prefix)
	}
	return nil
}

// CheckQuoted: nil when s, a value of the field named field written
// between double quotes, holds no quote, backslash or newline.
func CheckQuoted(field, s string) error {
	if strings.ContainsAny(s, "\"\\\n") {
		return fmt.Errorf("%s %q: holds a quote, a backslash or a newline", field, s)
	}
	return nil
}

// ReleaseError: a release name in two namespaces or more, which the
// deployer targets refuse (Releases): their objects, named after the
// releases, share one namespace.
type ReleaseError struct {
	Release    string
	Namespaces []string // in name order
}

func (e *ReleaseError) Error() string {
	ns := make([]string, len(e.Namespaces))
	for i, n := range e.Namespaces {
		ns[i] = fmt.Sprintf("%q", n)
	}
	return fmt.Sprintf("release %q is in namespaces %s and %s", e.Release, strings.Join(ns[:len(ns)-1], ", "), ns[len(ns)-1])
}

// Releases: nil when no release name is in two namespaces of results:
// else a *ReleaseError per release, in name order.
func Releases(results []*okdp.Result) error {
	namespaces := map[string][]string{}
	for _, res := range results {
		namespaces[res.Release] = append(namespaces[res.Release], res.Namespace)
	}
	var errs []error
	for _, release := range slices.Sorted(maps.Keys(namespaces)) {
		if ns := namespaces[release]; len(ns) > 1 {
			slices.Sort(ns)
			errs = append(errs, &ReleaseError{Release: release, Namespaces: ns})
		}
	}
	return errors.Join(errs...)
}

// UniqueReleases: Releases, each error naming objects, the objects of a
// target named after the releases, which share one namespace.
func UniqueReleases(results []*okdp.Result, objects string) error {
	err := Releases(results)
	if err == nil {
		return nil
	}
	var errs []error
	for _, e := range err.(interface{ Unwrap() []error }).Unwrap() {
		errs = append(errs, fmt.Errorf("%w: %s need distinct names", e, objects))
	}
	return errors.Join(errs...)
}

// OwnNamespaces: nil when no result is of one of namespaces, those the
// target writes its own objects in (its releases' objects, the engine's
// source): else an error per namespace that has one, in name order,
// naming what the target writes there. The compile refuses the engines'
// usual namespaces already (okdp.EngineNamespaces); a target that writes
// in another, by its options, refuses its projects too: a project's
// releases, with every verb of their namespace, would rewrite the engine's
// objects there.
func OwnNamespaces(results []*okdp.Result, namespaces map[string]string) error {
	have := map[string]bool{}
	for _, res := range results {
		if _, own := namespaces[res.Namespace]; own {
			have[res.Namespace] = true
		}
	}
	var errs []error
	for _, ns := range slices.Sorted(maps.Keys(have)) {
		errs = append(errs, fmt.Errorf("project %q: the namespace is reserved: it holds %s, no project's", ns, namespaces[ns]))
	}
	return errors.Join(errs...)
}

// Lines: a file built line by line (Add).
type Lines struct{ strings.Builder }

// Add: a line, format and args as fmt.Sprintf's.
func (l *Lines) Add(format string, args ...any) {
	fmt.Fprintf(&l.Builder, format, args...)
	l.WriteByte('\n')
}
